import {MAX_CELL_CHARACTERS} from './limits.js';
import {escapeHTML as esc,TextAreaField} from './kit.js';
import {guidanceFor} from './assessment-engine.js';
export const FRAMEWORKS=['CIS Critical Security Controls v6.1','HIPAA','ISO 27002:2013','NIST Cybersecurity Framework','NIST SP 800-171r1','NIST SP 800-53r4'];
const number=n=>Number.isFinite(n)?new Intl.NumberFormat(undefined,{maximumFractionDigits:2}).format(n):'—';
const pct=n=>Number.isFinite(n)?number(n)+'%':'Not scored';
const options=(value,items)=>items.map(([v,t])=>`<option value="${esc(v)}"${value===v?' selected':''}>${esc(t)}</option>`).join('');
const applicableOptions=[['unreviewed','Not reviewed'],['applicable','Applies'],['not-applicable','Does not apply — reason required']];
export function GuidanceView(q,r,data){
 const block=g=>g?.text?`<p class="original-guidance">${esc(g.text)}</p>${g.resultType==='boolean'?'<p>The original formula returns a Boolean value here; it provides no written instruction for this answer.</p>':''}`:'<p>No additional written guidance is specified for this response.</p>';
 if(q.kind!=='choice')return `<section id="workbook-guidance" class="workbook-guidance"><h3>Original workbook guidance</h3><p class="original-guidance">${esc(q.guidance||'No additional written guidance is specified.')}</p><p class="source-ref">CoSN K-12CVAT!E${q.row}</p></section>`;
 const a=r.answer;
 return `<section id="workbook-guidance" class="workbook-guidance"><h3>Original workbook guidance</h3>${a?block(guidanceFor(q.id,a,data)):`<p>Select the vendor’s answer to see the matching request for detail.</p><details><summary>Preview the Yes and No guidance</summary><h4>If Yes</h4>${block(guidanceFor(q.id,'Yes',data))}<h4>If No</h4>${block(guidanceFor(q.id,'No',data))}</details>`}<p class="source-ref">CoSN K-12CVAT!E${q.row} · Original wording; separate from our explanation.</p></section>`;
}
export function ResultView(result){
 return `<p class="review-caveat"><strong>Preliminary workbook calculation, not approval.</strong> Missing and unknown answers receive zero calculation points while remaining in the original denominator. They are not observed failures. Unknown is not a pass or fail. Review relevance, explanations and evidence before drawing a conclusion.</p><p class="calculation-coverage"><strong>${result.counts.recorded} of ${result.counts.included} included assessment responses recorded</strong> · ${result.counts.unknown} unknown · ${result.counts.unanswered} unanswered · ${result.counts.excluded} excluded by reasoned district decisions. General-information fields are not part of this calculation.</p><div class="score-overview"><div><span>Overall category average</span><strong>${pct(result.overall?.percentage)}</strong></div><div><span>Workbook letter band</span><strong>${esc(result.overall?.grade??'—')}</strong></div><div><span>Calculation</span><strong>${result.mode==='corrected'?'Independent corrections':'Original-compatible'}</strong></div></div><div class="table-wrap" tabindex="0" role="region" aria-label="Category scoring"><table><thead><tr><th scope="col">Category</th><th scope="col">Score / maximum</th><th scope="col">Percentage</th></tr></thead><tbody>${(result.categories||[]).map(c=>`<tr><th scope="row">${esc(c.section??c.category??c.prefix)}${c.included===false?'<span class="table-note">Excluded by district decision</span>':''}</th><td>${number(c.score)} / ${number(c.maxScore)}</td><td>${c.included===false?'Excluded':pct(c.percentage)}</td></tr>`).join('')}</tbody></table></div><p>The overall result averages included category percentages. It is not a percentage of answered questions. A–F bands reproduce the workbook thresholds; they are not security certifications.</p><details class="calculation-notes"><summary>Calculation details and source limitations</summary><ul>${(result.warnings||[]).map(w=>`<li>${esc(typeof w==='string'?w:w.message??JSON.stringify(w))}</li>`).join('')}</ul><p>Original-compatible mode retains the supplied workbook’s answer interpretations and known calculation defects. Independent corrections repair documented missing lookups and apply only documented district exclusions. COMP-05’s favorable answer is unchanged unless an analyst explicitly records an interpretation below. Neither mode represents CoSN approval.</p></details><h3>High-weight questions requiring attention</h3><p>Workbook “High Risk” means a source weight over 20. This is a prioritization aid, not a finding that a product is unsafe.</p>${result.highRisk?.length?`<ul class="analyst-attention">${result.highRisk.map(q=>`<li><a href="#question/${esc(q.id)}">${esc(q.id)} · ${esc(q.text||q.question||'Review response')}</a></li>`).join('')}</ul>`:'<p>No items match this calculation’s high-weight attention filter. This does not establish safety.</p>'}`;
}
export function AnalystView(draft,questions,source,corrected){
 const r=draft.review,result=r.calculationMode==='corrected'?corrected:source,assessment=questions.filter(q=>!q.id.startsWith('GNRL')&&!q.id.startsWith('DATE')),sections=[...new Set(assessment.map(q=>q.section))];
 return `<div class="analyst-page"><header class="page-heading"><h1>District analyst review</h1><p>Review the vendor’s evidence, document relevance and complete the workbook’s analyst steps.</p></header><nav class="analyst-jump" aria-label="District review sections"><a href="#analyst-results" data-local-anchor>Calculations</a><a href="#qualitative-review" data-local-anchor>Company narratives</a><a href="#applicability-review" data-local-anchor>Applicability</a><a href="#standards-review" data-local-anchor>Crosswalk</a><a href="#analyst-exchange" data-local-anchor>Save & exchange</a></nav><section class="analyst-settings"><label>Institution’s security framework<input id="review-framework" list="framework-options" value="${esc(r.framework)}" maxlength="${MAX_CELL_CHARACTERS}"><datalist id="framework-options">${FRAMEWORKS.map(f=>`<option value="${esc(f)}">`).join('')}</datalist></label><label>Date prepared<input id="review-date" value="${esc(r.preparedDate||'')}" maxlength="${MAX_CELL_CHARACTERS}" placeholder="yyyy-mm-dd"></label><label>Calculation method<select id="review-method">${options(r.calculationMode,[['source','Original-compatible — known workbook defects'],['corrected','Independent corrections & district applicability']])}</select></label><p>Framework names are historical source references. A custom name is retained as context; it creates no new control mapping.</p></section><section id="analyst-results"><h2>Workbook calculations</h2><p id="calculation-status" role="status"></p><div id="analyst-calculations">${ResultView(result)}</div><details><summary>Compare original-compatible and independently corrected results</summary><div class="table-wrap"><table><thead><tr><th>Method</th><th>Category average</th><th>Letter band</th></tr></thead><tbody><tr><th>Original-compatible</th><td id="source-average">${pct(source.overall?.percentage)}</td><td id="source-grade">${esc(source.overall?.grade??'—')}</td></tr><tr><th>Independent corrections</th><td id="corrected-average">${pct(corrected.overall?.percentage)}</td><td id="corrected-grade">${esc(corrected.overall?.grade??'—')}</td></tr></tbody></table></div></details></section><section id="qualitative-review"><h2>Company narratives</h2><p>The workbook handles COMP-01, COMP-02 and COMP-09 outside its aggregate score. Record your district’s judgment and a score from 0 to 10 for each. This is analyst work, not a vendor answer.</p>${['COMP-01','COMP-02','COMP-09'].map((id,i)=>{const q=questions.find(q=>q.id===id),a=r.qualitative[id]||{};return `<details class="qualitative-item"><summary>${id} · ${esc(q.text)}</summary><h3>Vendor response</h3><p class="vendor-narrative">${esc(draft.records[id]?.answer||'No vendor response recorded.')}</p><a href="#question/${id}">Open vendor response and analyst reference</a><div class="analyst-pair"><label>District judgment (“Compliant?” in source)<select data-qualitative="${id}" data-property="compliant">${options(a.compliant||'',[['','Not reviewed'],['Yes','Meets this district’s needs'],['No','Does not meet this district’s needs']])}</select></label><label>Analyst score: 0–10<input type="number" min="0" max="10" step="any" data-qualitative="${id}" data-property="score" value="${a.score??''}"></label></div>${TextAreaField({id:'qualitative-'+id,label:'Analyst rationale / evidence reference',value:a.notes||'',rows:3})}<p class="source-ref">Analyst Report!G${33+i}:H${33+i}</p></details>`}).join('')}<div id="adjusted-company">${AdjustedCompanyView(result)}</div></section><section id="applicability-review"><h2>Product applicability</h2>${Object.entries(r.favorableOverrides).filter(([id,v])=>id!=="COMP-05"&&v.answer).length?`<aside class="review-caveat"><h3>Other imported district interpretations</h3><p>These explicitly saved interpretations affect only independent corrections. Review them before using its result.</p><ul>${Object.entries(r.favorableOverrides).filter(([id,v])=>id!=="COMP-05"&&v.answer).map(([id,v])=>`<li><strong>${esc(id)} · favorable ${esc(v.answer)}</strong><p>${esc(v.reason||"No rationale: not applied.")}</p></li>`).join("")}</ul></aside>`:""}<p>Not every category applies to every product. Unknown means a vendor response is missing. “Does not apply” is a separate district decision and needs a reason. Exclusions affect only independent corrections; original-compatible mode retains the source denominator.</p><details><summary>Review category relevance</summary>${sections.map((section,index)=>{const a=r.categoryApplicability[section]||{};return `<div class="applicability-row"><label>${esc(section)}<select data-category="${esc(section)}">${options(a.state||'unreviewed',applicableOptions)}</select></label>${TextAreaField({id:"category-reason-"+index,label:"Reason / supporting reference",value:a.reason||"",rows:2})}</div>`}).join('')}</details><details><summary>Review individual question relevance</summary>${assessment.map(q=>{const a=r.applicability[q.id]||{};return `<div class="applicability-row"><label><a href="#question/${q.id}">${q.id}</a> · ${esc(q.text)}<select data-applicability="${q.id}">${options(a.state||'unreviewed',applicableOptions)}</select></label>${TextAreaField({id:"applicability-reason-"+q.id,label:"Reason / supporting reference",value:a.reason||"",rows:2})}</div>`}).join('')}</details><details><summary>COMP-05: document an independent interpretation</summary><p>The source asks about a security event but favors Yes. CoSN’s intended interpretation is unresolved. Source-compatible mode always retains Yes. An independent interpretation needs a district rationale.</p><label>Favorable response in independently corrected mode<select id="review-interpretation">${options(r.favorableOverrides['COMP-05']?.answer||'',[['','Keep the source interpretation (Yes)'],['Yes','District interpretation: Yes'],['No','District interpretation: No']])}</select></label>${TextAreaField({id:"review-interpretation-reason",label:"Reason for district interpretation",value:r.favorableOverrides["COMP-05"]?.reason||"",rows:3})}</details></section><section id="standards-review"><h2>Standards crosswalk</h2><p>All six source frameworks are available below. Mappings and versions come from Lite 4.1; they do not prove certification or current compliance.</p><label>Display framework<select id="crosswalk-view"><option value="all">All six frameworks</option>${FRAMEWORKS.map(f=>`<option value="${esc(f)}"${r.framework===f?' selected':''}>${esc(f)}</option>`).join('')}</select></label><div id="crosswalk-table">${CrosswalkView(questions,FRAMEWORKS.includes(r.framework)?r.framework:'all')}</div><button id="export-crosswalk">Download crosswalk CSV</button><details><summary>Source control descriptions</summary><div id="control-dictionary"></div></details></section><section><h2>Overall analyst notes</h2>${TextAreaField({id:'analyst-notes',label:'Review rationale, limitations and next steps',value:r.analystNotes||'',rows:5})}<p>Keep confidential documents in your district’s approved system. Record references here; do not add student personal information.</p></section><section id="analyst-exchange"><h2>Save, reopen or transfer the complete assessment</h2><p>JSON and Excel backups include vendor answers, analyst decisions, applicability, classroom notes and request edits. Excel also retains the original workbook sheets and attribution. Nothing sends automatically.</p><div class="actions"><button id="analyst-json" class="primary">Save JSON backup</button><button id="analyst-xlsx">Download editable Excel workbook</button><button id="analyst-print">Print complete assessment report</button></div><label for="import">Open a JSON backup or completed Excel workbook</label><input type="file" id="import" accept=".json,.xlsx,application/json,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"><p id="import-error" role="alert"></p><label class="check"><input id="persist" type="checkbox">Keep a draft on this device</label><p id="analyst-save-status" role="status"></p><p><a href="#questions">Return to vendor questions</a> · <a href="#about">Source, calculation changes and limitations</a></p></section></div>`;
}
export function AdjustedCompanyView(result){const c=result.adjustedCompany||{};return `<h3>Adjusted company score</h3><p>${number(c.baseScore)} aggregate company points + ${number(c.manualScore)} analyst points = <strong>${number(c.score)}</strong>. This is the workbook’s separate adjusted company total, not an updated overall percentage.${c.complete?'':' Narrative review is incomplete.'}</p>`}
export function CrosswalkView(questions,framework='all'){const fs=framework==='all'?FRAMEWORKS:[framework];return `<div class="table-wrap crosswalk-matrix" tabindex="0" role="region" aria-label="Original standards crosswalk"><table><thead><tr><th scope="col">Original question</th>${fs.map(f=>`<th scope="col">${esc(f)}</th>`).join('')}</tr></thead><tbody>${questions.filter(q=>!q.id.startsWith('GNRL')&&!q.id.startsWith('DATE')).map(q=>`<tr><th scope="row"><a href="#question/${q.id}">${q.id}</a><span class="table-note">${esc(q.text)}</span></th>${fs.map(f=>`<td>${esc(q.crosswalk[f]||'No mapping in source')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
export function crosswalkCSV(questions){const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';return '\uFEFF'+[['ID','Original question',...FRAMEWORKS],...questions.filter(q=>!q.id.startsWith('GNRL')&&!q.id.startsWith('DATE')).map(q=>[q.id,q.text,...FRAMEWORKS.map(f=>q.crosswalk[f]||'')])].map(r=>r.map(cell).join(',')).join('\r\n')}
export function PrintAssessmentView(draft,questions,result,data){
 const text=v=>esc(v||'Not recorded').replaceAll('\n','<br>');
 const r=draft.review;
 const intakeLabels={tool:'Tool',website:'Website',use:'Classroom use',data:'Expected data context',help:'Review question',expectedData:'Teacher expects these data types',dataUnknown:'Vendor confirmation still needed'};
 return `<article><h1>CoSN CVAT · Complete assessment record</h1><p>Independent adaptation · K-12CVAT Lite 4.1 · ${esc(new Date().toISOString())}</p><p>Source: ${esc(data.sourceURL)}<br>Source SHA-256: ${esc(data.sourceSHA256)}</p><p>CoSN / EDUCAUSE · CC BY-NC-SA 4.0. Preliminary workbook calculations and district judgments; no approval or certification.</p><h2>Classroom context · added workflow</h2><dl>${Object.entries(draft.intake).map(([k,v])=>`<dt>${esc(intakeLabels[k]||k)}</dt><dd>${text(Array.isArray(v)?v.join(', '):typeof v==='boolean'?v?'Yes':'No':String(v??''))}</dd>`).join('')}</dl><h2>Prepared handoff · added workflow</h2><p><strong>${text(draft.request.subject)}</strong></p><p>${text(draft.request.body)}</p><h2>Institution review</h2><p>Framework: ${text(r.framework)}<br>Date prepared: ${text(r.preparedDate)}<br>Method: ${r.calculationMode==='source'?'Original-compatible':'Independent corrections'}</p>${ResultView(result)}<h2>Manual company review</h2>${['COMP-01','COMP-02','COMP-09'].map(id=>{const q=r.qualitative[id];return `<h3>${id}</h3><p>District judgment: ${text(q.compliant)} · Analyst score: ${q.score??'Not reviewed'} / 10</p><p>${text(q.notes)}</p>`}).join('')}${AdjustedCompanyView(result)}<h2>District applicability decisions</h2>${['categoryApplicability','applicability'].map(key=>`<h3>${key==='applicability'?'Questions':'Categories'}</h3>${Object.entries(r[key]).length?Object.entries(r[key]).map(([id,v])=>`<p><strong>${esc(id)}</strong> · ${esc(v.state)}<br>${text(v.reason)}</p>`).join(''):'<p>No decisions recorded.</p>'}`).join('')}<h2>Independent favorable-answer interpretations</h2>${Object.entries(r.favorableOverrides).length?Object.entries(r.favorableOverrides).map(([id,v])=>`<p>${esc(id)} · ${text(v.answer)}<br>${text(v.reason)}</p>`).join(''):'<p>No overrides recorded.</p>'}<h2>Overall analyst notes</h2><p>${text(r.analystNotes)}</p><h2>All original responses and evidence</h2>${questions.map(q=>{const a=draft.records[q.id]||{};return `<section class="print-record"><h3>${esc(q.id)} · ${esc(q.text)}</h3><p>Section: ${esc(q.section)} · Responsible: ${esc(q.owner)}</p><p><strong>Response:</strong> ${a.unknown&&!a.answer?'Not yet known':text(a.answer)}</p><p><strong>Additional information:</strong> ${text(a.additional)}</p><p><strong>Evidence reference:</strong> ${text(a.evidence)}</p><p>Provided by: ${text(a.provider)} · Follow-up: ${a.flag?'Yes':'No'}</p></section>`}).join('')}<h2>Source limitations</h2><p>Unknown and missing responses receive zero source calculation points and stay in its denominator. They are not observed control failures. The original workbook has missing COMP-07/08 lookups, an incomplete high-risk range, ambiguous COMP-05 interpretation and broken conditional-formatting references. Independent corrections and reasoned district exclusions are separate from original-compatible results. Refer to the editable Excel export for the original sheets, exact formulas, all analyst reference text, standards mappings and full transfer state.</p></article>`;
}
